var dbg_logger = DbgLogger {};
const logger1 = Logger.implBy(&dbg_logger);
logger1.log("Hello1");
logger1.log("Hello2");
logger1.setLevel(2);
logger1.log("Hello3");
var file_logger = try FileLogger.init("log.txt");
defer file_logger.deinit();
const logger2 = Logger.implBy(&file_logger);
